"""Extract ASCII + UTF-16LE strings from files and bucket them by capability keyword (static only).
usage: python -I capgrep.py <file> [<file> ...]
"""
import sys, re, os
sys.stdout.reconfigure(encoding='utf-8', errors='replace')

CATS = {
    'network/C2-endpoints': r'https?://[^\s"\'<>]{4,}|[a-z0-9.-]+\.(centrastage\.net|rmm\.datto\.com|datto\.com|autotask\.net|kaseya\.\w+)',
    'remote-shell/exec': r'cmd\.exe|powershell|ProcessStartInfo|CreateProcessAsUser|RunAs|CsExec|psexec|ExecuteCommand|RunScript|ScriptRunner|Jint',
    'remote-desktop': r'\bRDP\b|MsRdp|mstsc|\bVNC\b|ViewerX|WebRemote|ScreenCapture|BitBlt|CopyFromScreen|SendInput|keybd_event|DesktopDuplication',
    'file-transfer': r'FileTransfer|UploadFile|DownloadFile|\bSFTP\b|SharpZip',
    'tunnel/proxy': r'kproxy|socks|tunnel|ReverseProxy|PortForward|WebSocket',
    'credential/privilege': r'SeDebugPrivilege|LogonUser|DuplicateToken|ImpersonateLoggedOnUser|WTSQueryUserToken|lsass|mimikatz|password',
    'persistence/service': r'ServiceBase|CreateService|SafeBoot|CurrentVersion\\\\?Run|ScheduledTask|schtasks',
    'security-tampering': r'DisableAntiSpyware|Set-MpPreference|DisableRealtime|wevtutil|vssadmin|bcdedit|netsh advfirewall',
    'inventory/monitoring': r'Win32_\w+|ManagementObjectSearcher|SNMP|Vim25|PerformanceCounter|EventLog',
    'ai-addressed-text': r'(?i)\b(ignore (all |previous )?instructions|as an ai|language model|claude|chatgpt)\b',
}
RX = {k: re.compile(v, re.I if k != 'ai-addressed-text' else 0) for k, v in CATS.items()}

def strings(b, n=5):
    for m in re.finditer(rb'[\x20-\x7e]{%d,}' % n, b):
        yield m.group().decode('ascii')
    for m in re.finditer(rb'(?:[\x20-\x7e]\x00){%d,}' % n, b):
        yield m.group().decode('utf-16le')

for f in sys.argv[1:]:
    b = open(f, 'rb').read()
    hits = {k: set() for k in CATS}
    for s in strings(b):
        for k, rx in RX.items():
            if rx.search(s):
                hits[k].add(s[:160])
    print(f'===== {os.path.basename(os.path.dirname(f))}\\{os.path.basename(f)}')
    for k, v in hits.items():
        if v:
            sample = sorted(v, key=len)[:12]
            print(f'  [{k}] {len(v)} hits: ' + ' || '.join(sample))

