    """Description when exports forward into ``<own name><suffix>.dll`` (the renamed original), else ``""``."""
    own = {stem for stem in (_stem(facts.export_dll_name), _stem(facts.version("OriginalFilename")), _stem(facts.version("InternalName"))) if len(stem) >= 3}
