"""Regression: count plugin static findings (weight > 0) and family hits over clean System32 PE files.
usage: python -I plugin_regression.py <plugin_root> <dir> [max_files]
"""
import sys, os, re, collections
sys.path.insert(0, sys.argv[1])
from ida_ai_malware_analyst_plugin.analysis import pe_static, family_markers  # noqa: E402

root, limit = sys.argv[2], int(sys.argv[3]) if len(sys.argv) > 3 else 400
files = sorted((os.path.join(root, f) for f in os.listdir(root) if f.lower().endswith((".dll", ".exe"))),
               key=lambda p: -os.path.getsize(p) if os.path.isfile(p) else 0)[:limit]
counts = collections.Counter(); examples = collections.defaultdict(list); scanned = 0
for path in files:
    try:
        facts = pe_static.parse_pe_file(path)
        if facts is None or not facts.is_pe:
            continue
        scanned += 1
        for finding in pe_static.static_findings(facts):
            if finding.weight > 0:
                counts[finding.category] += 1
                if len(examples[finding.category]) < 6:
                    examples[finding.category].append("{0}: {1}".format(os.path.basename(path), finding.description[:140]))
        if os.path.getsize(path) < 8 * 1024 * 1024:
            data = open(path, "rb").read()
            strings = [m.group().decode("ascii") for m in re.finditer(rb"[\x20-\x7e]{5,}", data)]
            strings += [m.group().decode("utf-16le") for m in re.finditer(rb"(?:[\x20-\x7e]\x00){5,}", data)]
            for hit in family_markers.match_families(strings):
                counts["family:" + hit.family] += 1
                if len(examples["family:" + hit.family]) < 6:
                    examples["family:" + hit.family].append("{0}: {1}".format(os.path.basename(path), hit.markers[:4]))
    except Exception as exc:  # keep going on odd files
        counts["error"] += 1
print("scanned", scanned, "files (largest first) in", root)
for key, value in counts.most_common():
    print("  {0:40s} {1}".format(key, value))
    for example in examples[key]:
        print("      ", example)

