_BOUNDARY_CACHE: dict = {}


def _present(marker: str, joined: str, boundary: bool) -> bool:
    if marker not in joined:
        return False
    if not boundary:
        return True
    pattern = _BOUNDARY_CACHE.get(marker)
    if pattern is None:
        import re

        left = r"(?<![a-z0-9])" if marker[:1].isalnum() else ""
        right = r"(?![a-z0-9])" if marker[-1:].isalnum() else ""
        pattern = _BOUNDARY_CACHE[marker] = re.compile(left + re.escape(marker) + right)
    return pattern.search(joined) is not None

