"""PUP false-positive regression over clean software (recursive, capped). Static only.
usage: python -I pup_regression.py <plugin_root> <max_files> <dir> [<dir> ...]
"""
import sys, os, re, collections
sys.path.insert(0, sys.argv[1])
from ida_ai_malware_analyst_plugin.analysis import pe_static, family_markers  # noqa: E402

limit = int(sys.argv[2])
paths = []
for root in sys.argv[3:]:
    for base, _dirs, names in os.walk(root):
        for name in names:
            if name.lower().endswith((".dll", ".exe", ".sys")):
                paths.append(os.path.join(base, name))
paths = paths[:limit]
counts = collections.Counter(); examples = collections.defaultdict(list); scanned = 0
for path in paths:
    try:
        if os.path.getsize(path) > 48 * 1024 * 1024:
            continue
        facts = pe_static.parse_pe_file(path)
        if facts is None or not facts.is_pe:
            continue
        scanned += 1
        data = open(path, "rb").read()
        texts = [m.group().decode("ascii") for m in re.finditer(rb"[\x20-\x7e]{5,}", data)]
        texts += [m.group().decode("utf-16le") for m in re.finditer(rb"(?:[\x20-\x7e]\x00){5,}", data)]
        texts += [value for _k, value in facts.version_info]
        if facts.signed and facts.signer:
            texts.append("signer: " + facts.signer)
        for hit in family_markers.match_families(texts):
            if hit.kind in ("pup", "hacktool") or hit.family.startswith(("Certify", "Rubeus", "Seatbelt", "SharpDPAPI", "ForgeCert")):
                key = "{0}:{1}".format(hit.kind, hit.label or hit.family)
                counts[key] += 1
                if len(examples[key]) < 5:
                    examples[key].append("{0}  {1}  {2}".format(path, hit.family, hit.markers[:4]))
    except Exception:
        counts["error"] += 1
print("scanned", scanned, "PE files")
for key, value in counts.most_common():
    print("  {0:45s} {1}".format(key, value))
    for example in examples[key]:
        print("      ", example)

