def collect_facts(overview: Any, pe: Any = None) -> AiFacts:
    strings = [(getattr(item, "address", -1), getattr(item, "value", "")) for item in getattr(overview, "strings", ()) or ()]
    decoded: List[str] = []
    resolved: List[str] = []
    for item in getattr(getattr(overview, "code_signals", None), "functions", ()) or ():
        for entry in getattr(item, "decoded_strings", ()) or ():
            text = getattr(entry, "text", None) or (entry[1] if isinstance(entry, (tuple, list)) and len(entry) > 1 else entry)
            if isinstance(text, str) and text.strip():
                decoded.append(text.strip()[:MAX_STRING_LENGTH])
        for entry in getattr(item, "api_hashes", ()) or ():
            if isinstance(entry, (tuple, list)):
                names = [part for part in entry if isinstance(part, str)]
                if names:
                    resolved.append(names[-1])
    for item in getattr(getattr(overview, "code_signals", None), "stack_strings", ()) or ():
        text = getattr(item, "text", None)
        if isinstance(text, str) and text.strip():
            decoded.append(text.strip()[:MAX_STRING_LENGTH])
    imports = tuple(dict.fromkeys(
        "{0}!{1}".format(getattr(item, "dll", "") or "?", getattr(item, "name", "") or "?")
        for item in getattr(overview, "imports", ()) or ()
    ))[:MAX_IMPORTS]
    binary: Dict[str, Any] = {
        "file_type": getattr(overview, "file_type", None),
        "architecture": getattr(overview, "architecture", None),
        "bitness": getattr(overview, "bitness", None),
        "sections": [getattr(item, "name", "") for item in getattr(overview, "segments", ()) or ()][:32],
        "tls_callbacks": getattr(overview, "has_tls_callbacks", None),
        "resources_present": getattr(overview, "resources_present", None),
        "function_count": len(getattr(overview, "functions", ()) or ()),
    }
    if pe is not None and getattr(pe, "is_pe", False):
        binary.update({
            "signed": bool(getattr(pe, "signed", False)),
            "signer": getattr(pe, "signer", "") or "",
            "version_info": dict(getattr(pe, "version_info", ()) or ()),
            "exports": [getattr(item, "name", "") for item in (getattr(pe, "exports", ()) or ())[:40]],
            "wrappers": list(getattr(pe, "wrappers", ()) or ()),
            "overlay_size": getattr(pe, "overlay_size", 0),
            "embedded_executables": list(getattr(pe, "embedded_executables", ()) or ())[:8],
            "entry_stub": getattr(pe, "entry_stub", "") or "",
        })
    texts = [text for _address, text in strings] + decoded + [name.split("!", 1)[-1] for name in imports]
    families = tuple("{0} ({1})".format(hit.family, ", ".join(hit.markers[:4])) for hit in match_families(texts))
    return AiFacts(binary, imports, select_strings(strings), tuple(dict.fromkeys(decoded))[:300],
                   tuple(dict.fromkeys(resolved))[:300], families)


